#!/usr/bin/env python3
"""Generate Modules/Contracts/FeatureFrame.swift from ml/schema/feature_schema.json.
Run from the repo root: python3 ml/schema/gen_feature_frame.py"""
import json, pathlib

root = pathlib.Path(__file__).resolve().parents[2]
schema = json.loads((root / "ml/schema/feature_schema.json").read_text())
feats = schema["features"]
lines = [
    "// GENERATED by ml/schema/gen_feature_frame.py from ml/schema/feature_schema.json. Do not edit.",
    "import Foundation",
    "",
    "/// One 10 Hz sample of numeric attention features. Field order == model input order.",
    "/// Contains numbers only: no images, video or face mesh are ever stored.",
    "public struct FeatureFrame: Codable, Equatable, Sendable {",
    "    /// Seconds since session start.",
    "    public var t: Double",
]
for f in feats:
    lines.append(f"    /// {f['desc']} [{f['unit']}]")
    lines.append(f"    public var {f['name']}: Float = 0")
lines += [
    "",
    "    public init(t: Double) { self.t = t }",
    "",
    f"    public static let schemaVersion = {schema['version']}",
    f"    public static let rateHz: Double = {schema['rate_hz']}",
    f"    public static let stateWindowSeconds: Double = {schema['window_state_s']}",
    f"    public static let forecastWindowSeconds: Double = {schema['window_forecast_s']}",
    f"    public static let forecastHorizonSeconds: Double = {schema['forecast_horizon_s']}",
    "",
    "    /// Feature names in model input order (excludes `t`).",
    "    public static let featureNames: [String] = [",
    *[f'        "{f["name"]}",' for f in feats],
    "    ]",
    "",
    "    /// Values in `featureNames` order.",
    "    public var vector: [Float] {",
    "        [" + ", ".join(f["name"] for f in feats) + "]",
    "    }",
    "",
    "    /// Inverse of `vector`.",
    "    public init(t: Double, vector v: [Float]) {",
    f"        precondition(v.count == {len(feats)}, \"FeatureFrame vector must have {len(feats)} values\")",
    "        self.t = t",
    *[f"        {f['name']} = v[{i}]" for i, f in enumerate(feats)],
    "    }",
    "}",
    "",
]
out = root / "Modules/Contracts/FeatureFrame.swift"
out.write_text("\n".join(lines))
print(f"wrote {out} ({len(feats)} features)")
